import { describe, expect, it } from "vitest";
import type { CalendarDate, CalendarDefinition, DateStyle } from "@/lib/bindings";
import fixtures from "./calendar-fixtures.json";
import {
  daysInMonth,
  daysInYear,
  epochOffsetOf,
  formatDate,
  fromDate,
  toDate,
  yearIndexOf,
} from "./calendar";

// The fixtures are generated by a Rust test from the backend calendar module.
// Every sample must be reproduced exactly by the TypeScript port.
interface Sample {
  day: number;
  date: CalendarDate;
  formats: Record<DateStyle, string>;
  daysInYear: number;
  daysInMonth: number;
}
interface FixtureCalendar {
  name: string;
  definition: CalendarDefinition;
  samples: Sample[];
}
const calendars = (fixtures as unknown as { calendars: FixtureCalendar[] }).calendars;
const STYLES: DateStyle[] = ["full", "short", "monthYear", "year", "month", "day"];

describe("calendar golden fixtures", () => {
  it("covers the four expected calendars", () => {
    expect(calendars.map((c) => c.name)).toEqual(["default", "gregorian", "moons", "uneven"]);
    for (const c of calendars) expect(c.samples.length).toBeGreaterThan(50);
  });

  describe.each(calendars)("$name", ({ definition, samples }) => {
    it("toDate matches every sample (including weekday)", () => {
      for (const s of samples) expect(toDate(definition, s.day), `day ${s.day}`).toEqual(s.date);
    });

    it("formats every style identically", () => {
      for (const s of samples) {
        for (const style of STYLES) {
          expect(formatDate(definition, s.day, style), `day ${s.day} ${style}`).toBe(
            s.formats[style],
          );
        }
      }
    });

    it("fromDate inverts toDate", () => {
      for (const s of samples) {
        const { eraIndex, year, month, day } = s.date;
        expect(fromDate(definition, eraIndex, year, month, day), `day ${s.day}`).toBe(s.day);
      }
    });

    it("daysInYear and daysInMonth match", () => {
      for (const s of samples) {
        const a = yearIndexOf(definition, s.day - epochOffsetOf(definition));
        expect(daysInYear(definition, a), `year of day ${s.day}`).toBe(s.daysInYear);
        expect(daysInMonth(definition, a, s.date.month), `month of day ${s.day}`).toBe(
          s.daysInMonth,
        );
      }
    });
  });
});
